    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def fairCandySwap(self, aliceSizes: List[int], bobSizes: List[int]) -> List[int]:\n        sumA, sumB = sum(aliceSizes), sum(bobSizes)\n        delta = (sumA - sumB) // 2\n        rec = set(aliceSizes)\n        ans = None\n        for y in bobSizes:\n            x = y + delta\n            if x in rec:\n                ans = [x, y]\n                break\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.fairCandySwap(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
